const fs = require('fs');
const path = require('path');

const rootDir = path.resolve(__dirname, '..');
const apiPhpPath = path.join(rootDir, 'api.php');
const targetJsPath = path.join(rootDir, 'utils', 'bundledApi.js');

if (!fs.existsSync(apiPhpPath)) {
  console.error('[sync-bundled-api] api.php not found at', apiPhpPath);
  process.exit(1);
}

const apiContent = fs.readFileSync(apiPhpPath, 'utf8');

const match = apiContent.match(/define\('UNRAID_API_VERSION',\s*'([^']+)'\);/);
if (!match) {
  console.error('[sync-bundled-api] UNRAID_API_VERSION not found in api.php');
  process.exit(1);
}

const version = match[1];
console.log(`[sync-bundled-api] Bundling api.php version: ${version} (${(apiContent.length / 1024).toFixed(1)} KB)`);

const fileContent = `/**
 * AUTO-GENERATED FILE - DO NOT EDIT DIRECTLY
 * Generated by scripts/sync-bundled-api.js
 * Source: api.php (Version: ${version})
 */

export const BUNDLED_API_VERSION = ${JSON.stringify(version)};

export const BUNDLED_API_CODE = ${JSON.stringify(apiContent)};
`;

fs.writeFileSync(targetJsPath, fileContent, 'utf8');
console.log('[sync-bundled-api] Successfully generated:', targetJsPath);
